			/* @Override */
			public Component getTableCellRendererComponent(GTableCellRenderingData data) {

				JLabel label = (JLabel) base.getTableCellRendererComponent(data);

				bool isSelected = data.isSelected();

				label.setText(" ");

				Equate eq = (Equate) data.getRowObject();
				if (eq == null) {
					return label;
				}

				JTable table = data.getTable();
				if (!eq.isValidUUID()) { // Error equate
					label.setForeground(getErrorForegroundColor(isSelected));
				}
				else if (!eq.isEnumBased()) { // User label
					label.setForeground(
						(isSelected) ? table.getSelectionForeground() : FG_USER_DEFINED);
				}

				string tooltip = getEquateToolTip(eq);
				label.setToolTipText(tooltip);

				label.setText((string) data.getValue());
				return label;
			}

